$state=$sub['status']==='active' && $sub['end_date']<date('Y-m-d') ? 'Expiré' : ($sub['status']==='active' && $sub['start_date']>date('Y-m-d') ? 'À venir' : (['active'=>'Actif','frozen'=>'Gelé','cancelled'=>'Annulé'][$sub['status']] ?? $sub['status']));
$stateLabels=['open'=>'En cours','resumed'=>'Repris','cancelled'=>'Annulé avec l’abonnement']; require __DIR__.'/management_header.php';
?>
<section class="card management-table"><div class="card-head"><div><h3>Abonnement #<?= (int)$sub['id'] ?> · <?= e($sub['plan']) ?></h3><p><?= e($sub['first_name'].' '.$sub['last_name']) ?> · <?= e($sub['card_number'] ?: 'Sans carte') ?></p></div><a class="text-link" href="index.php?page=subscriptions">← Abonnements</a></div><dl class="member-profile-details"><div><dt>Statut actuel</dt><dd><?= e($state) ?></dd></div><div><dt>Début</dt><dd><?= e(date('d/m/Y',strtotime($sub['start_date']))) ?></dd></div><div><dt>Fin actuelle</dt><dd><?= e(date('d/m/Y',strtotime($sub['end_date']))) ?></dd></div><div><dt>Prix fixé</dt><dd><?= $sub['agreed_price']===null ? 'À vérifier' : e(dt($sub['agreed_price'])) ?></dd></div></dl><p class="form-hint">Le nom de formule et la fin affichés sont les valeurs actuelles. Une reprise peut avoir prolongé la fin.</p><a class="text-link" href="index.php?page=member_profile&amp;id=<?= (int)$sub['member_id'] ?>">Voir la fiche membre →</a></section>
<section class="card management-table"><div class="card-head"><div><h3>Historique des gels</h3><p><?= (int)$detail['total'] ?> gel(s) enregistré(s)</p></div></div>
<?php if ($detail['openCount']>1): ?><p class="notice" role="status">Plusieurs gels ouverts sont associés à cet abonnement. Faites vérifier les données par un administrateur.</p><?php elseif ($sub['status']==='frozen' && $detail['openCount']===0): ?><p class="notice" role="status">Ce gel ne possède pas de date de début enregistrée. Il peut s’agir d’un ancien gel : vérifiez les justificatifs avec un administrateur avant toute régularisation. La reprise automatique n’est pas disponible sans historique ouvert.</p><?php elseif ($sub['status']!=='frozen' && $detail['openCount']>0): ?><p class="notice" role="status">Un gel ouvert est associé à un abonnement qui n’est pas gelé. Faites vérifier les données par un administrateur.</p><?php endif; ?>
<div class="table-scroll"><table><thead><tr><th>DÉBUT DU GEL</th><th>FIN DU GEL</th><th>ÉTAT</th><th>JOURS CRÉDITÉS</th><th>SAISI PAR</th><th>CLÔTURÉ PAR</th></tr></thead><tbody><?php foreach ($detail['freezes'] as $freeze): ?><tr><td><?= e(date('d/m/Y',strtotime($freeze['frozen_on']))) ?></td><td><?= $freeze['resumed_on'] ? e(date('d/m/Y',strtotime($freeze['resumed_on']))) : '—' ?></td><td><?= e($stateLabels[$freeze['state']] ?? $freeze['state']) ?></td><td><?= $freeze['state']==='resumed' && $freeze['credited_days']!==null ? (int)$freeze['credited_days'] : '—' ?></td><td><?= e($freeze['created_name'] ?: '—') ?></td><td><?= e($freeze['closed_name'] ?: '—') ?></td></tr><?php endforeach; ?><?php if (!$detail['freezes']): ?><tr><td colspan="6" class="empty">Aucun gel enregistré.</td></tr><?php endif; ?></tbody></table></div><p class="form-hint">La fin d’un gel annulé correspond à la date d’annulation, pas à une reprise. Les anciens gels sans date ne peuvent pas être reconstitués automatiquement.</p><div class="pagination"><?php if ($detail['page']>1): ?><a href="index.php?page=subscription_detail&amp;id=<?= (int)$sub['id'] ?>&amp;p=<?= $detail['page']-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= (int)$detail['page'] ?> / <?= max(1,(int)ceil($detail['total']/10)) ?></span><?php if ($detail['page']*10<$detail['total']): ?><a href="index.php?page=subscription_detail&amp;id=<?= (int)$sub['id'] ?>&amp;p=<?= $detail['page']+1 ?>">Suivant →</a><?php endif; ?></div></section>
